home.scss:
// Home page styles are scoped to avoid altering catalogue and shared components.
.twelve-home {
    --gutter: 56px;
    --section: 128px;
    background: #fff;
    color: #000;
    font-family: var(--sans);
    font-size: 16px;
    line-height: 1.45;
    container-type: inline-size;

    *, *::before, *::after { box-sizing: border-box; }
    h1, h2, p { margin: 0; }
    a { color: inherit; text-decoration: none; }
    a:focus-visible, button:focus-visible, input:focus-visible { outline: 2px solid var(--royal) !important; outline-offset: 4px; }
    button, input { font: inherit; color: inherit; border-radius: 0; }
    button { cursor: pointer; background: none; }
    img { display: block; max-width: 100%; }
    [hidden] { display: none !important; }
    .wrap { width: 100%; max-width: 1512px; margin: 0 auto; padding-inline: var(--gutter); }
    .pb-region { position: relative; }
    .section { padding-block: var(--section); }
    .section-sm { padding-block: 96px; }
    .eyebrow { display: block; font-family: var(--sans-ext); font-size: 14px; font-weight: 500; line-height: 1.2; letter-spacing: .025em; text-transform: uppercase; }
    .d-lg, .d-md, .d-xl { font-family: var(--sans); font-weight: 300; letter-spacing: 0; color: inherit; }
    .d-lg { font-size: clamp(30px, 3.6cqw, 52px); line-height: 1.08; }
    .d-md { font-size: clamp(24px, 2.4cqw, 34px); line-height: 1.14; }
    .d-xl { font-size: clamp(38px, 5.2cqw, 76px); line-height: 1.04; }
    .body, .body-sm, .lede, .fineprint { font-family: var(--serif); font-weight: 400; color: var(--ink-72); }
    .body { margin: 0; font-size: 16px; line-height: 1.45; }
    .body-sm { font-size: 15px; line-height: 1.45; margin: 5px 0; }
    .lede { font-size: clamp(17px, 1.25cqw, 20px); line-height: 1.42; }
    .fineprint { font-size: 15px; line-height: 1.45; }
    .hero { background: #000; }
    .hero-media { position: relative; aspect-ratio: 3.6 / 1; height: auto; overflow: hidden; background: #fff; }
    .hero-video { display: block; width: 100%; height: 100%; object-fit: cover; }
.hero-motion{
  position:absolute;right:var(--gutter);top:20px;z-index:4;display:inline-flex;align-items:center;gap:8px;
  padding:8px 12px;border:1px solid rgba(255,255,255,.45);color:#fff;
  font-family:var(--sans-ext);font-weight:500;font-size:9px;letter-spacing:.025em;
  text-transform:uppercase;opacity:.75;transition:opacity .25s,background .25s;
}
.hero-motion:hover{opacity:1;background:rgba(0,0,0,.35)}
.hero-motion .ico{width:8px;height:9px;border-left:2px solid #fff;border-right:2px solid #fff}
.hero-motion[aria-pressed="true"] .ico{
  border:0;width:0;height:0;border-left:8px solid #fff;border-top:5px solid transparent;border-bottom:5px solid transparent;
}

    .hero-motion { min-height: 0; line-height: normal; background: none; border-radius: 0; }
    .sec-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 48px; margin-bottom: 48px; }
    .section { line-height: normal; }
    .sec-head h2 { max-width: 16ch; }
    .sec-head .eyebrow { margin-bottom: 16px; }
    .tlink { display: inline-flex; align-items: center; gap: 9px; padding-bottom: 5px; font-family: var(--sans-ext); font-size: 14px; font-weight: 500; letter-spacing: .025em; line-height: normal; text-transform: uppercase; background: linear-gradient(#000, #000) left bottom / 100% 1px no-repeat; transition: background-size var(--dur) var(--ease); }
    .tlink:hover { background-size: 0 1px; }
    .arw { display: inline-block; transition: transform var(--dur) var(--ease); }
    .tlink:hover .arw { transform: translateX(5px); }
    .feat-cats { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 24px; }
    .feat-cat { display: block; position: relative; overflow: hidden; min-width: 0; align-self: start; }
    .feat-cat .ph { position: relative; overflow: hidden; display: block; isolation: isolate; aspect-ratio: 4 / 5; background-size: cover; background-position: center; background-color: #fff; transition: transform 1.2s var(--ease); }
    .feat-cat .ph::after { content: ''; position: absolute; inset: 0; background: radial-gradient(120% 90% at 50% 0%, rgba(255,255,255,.55), transparent 60%); pointer-events: none; }
    .feat-cat:hover .ph { transform: scale(1.045); }
    .feat-body { display: grid; gap: 10px; padding-top: 20px; align-content: start; }
    .feat-body .body-sm { max-width: 34ch; }
    .campaign { position: relative; overflow: hidden; }
    .campaign .ph { display: block; position: relative; height: clamp(420px, 52cqw, 640px); background: linear-gradient(168deg, #EFEEF3, #DEDCE8); }
    .campaign .ph::before { content: ''; position: absolute; inset: 0; z-index: 2; background: linear-gradient(90deg, rgba(0,0,0,.66), rgba(0,0,0,.12) 62%); }
    .campaign .ph::after { content: ''; position: absolute; inset: 0; background: radial-gradient(120% 90% at 50% 0%, rgba(255,255,255,.55), transparent 60%); }
    .campaign .art { position: absolute; inset: 0; display: flex; align-items: center; justify-content: flex-end; padding-right: 9%; }
    .campaign .art img { width: 66%; height: 66%; }
    .campaign-copy { position: absolute; inset: 0; z-index: 3; display: flex; align-items: center; color: #fff; }
    .campaign-copy .in { max-width: 1512px; width: 100%; margin: 0 auto; padding-inline: var(--gutter); }
    .campaign-copy h2 { max-width: 16ch; }
    .campaign-copy p { max-width: 42ch; margin-top: 24px; }
    .btn { display: inline-flex; align-items: center; justify-content: center; min-height: 48px; padding: 17px 30px; border: 1px solid rgba(255,255,255,.55); font-family: var(--sans-ext); font-size: 13px; font-weight: 500; letter-spacing: .025em; line-height: 1.2; text-transform: uppercase; color: #fff; transition: background .3s, color .3s; }
    .btn { position: relative; overflow: hidden; transition: color var(--dur) var(--ease), border-color var(--dur) var(--ease); }
    .btn::after { content: ''; position: absolute; inset: 0; z-index: 0; background: #fff; transform: translateY(101%); transition: transform var(--dur) var(--ease); }
    .btn > * { position: relative; z-index: 1; }
    .btn:hover { color: #000; border-color: #fff; }
    .btn:hover::after { transform: translateY(0); }
    .news { max-width: 640px; margin: 0 auto; text-align: center; }
    .news form { display: flex; align-items: center; border-bottom: 1px solid #000; margin-top: 32px; }
    .news input[type="email"] { flex: 1; min-width: 0; width: 100%; padding: 14px 2px; border: 0; background: none; box-shadow: none; font-family: var(--serif); font-size: 16px; }
    .news input:focus, .news input:focus-visible, .news button:focus, .news button:focus-visible { outline: none !important; box-shadow: none; }
    .news input::placeholder { color: var(--ink-52); }
    .news button { flex-shrink: 0; border: 0; min-height: 48px; padding: 14px 4px 14px 18px; font-family: var(--sans-ext); font-size: 10.5px; font-weight: 500; letter-spacing: .025em; text-transform: uppercase; }
    .news button:hover { color: var(--royal); }
    .news .fine { margin-top: 16px; color: var(--ink-52); }

    @media (max-width: 1360px) { --gutter: 40px; --section: 112px; }
    @media (max-width: 1180px) { --section: 96px; }
    @media (max-width: 980px) { --gutter: 32px; --section: 88px; }
    @media (max-width: 760px) {
        --gutter: 20px;
        --section: 64px;
        .section-sm { padding-block: 56px; }
        .sec-head { flex-direction: column; align-items: flex-start; gap: 16px; margin-bottom: 32px; }
        .sec-head h2 { max-width: none; }
        .feat-cats { display: flex; gap: 14px; overflow-x: auto; scroll-snap-type: x mandatory; margin-inline: calc(var(--gutter) * -1); padding-inline: var(--gutter); scroll-padding-left: var(--gutter); scrollbar-width: none; }
        .feat-cats::-webkit-scrollbar { display: none; }
        .feat-cat { flex: 0 0 76%; scroll-snap-align: start; }
        .feat-body .body-sm { max-width: none; }
        .campaign .ph { height: 460px; }
        .campaign .ph::before { background: linear-gradient(180deg, rgba(0,0,0,.2), rgba(0,0,0,.72)); }
        .campaign-copy { align-items: flex-end; padding-bottom: 36px; }
        .campaign .art { justify-content: center; padding-right: 0; }
        .campaign-copy h2, .campaign-copy p { max-width: none; }
    }
    @media (max-width: 390px) { --gutter: 16px; }
    @media (prefers-reduced-motion: reduce) { *, *::before, *::after { transition: none !important; scroll-behavior: auto !important; } }
}

// Editorial downloads replacing the former homepage newsletter.
#main-content .stay-inspired {
    min-height: 680px;
    padding: 70px 0 96px;
    background: #fff;
    color: #111;

    &__inner {
        display: grid;
        grid-template-columns: minmax(330px, 1fr) minmax(0, 2fr);
        gap: 48px;
        width: 100%;
        max-width: 1512px;
        margin: 0 auto;
        padding-inline: var(--gutter);
    }

    &__intro {
        padding-top: 90px;

        h2 {
            margin: 28px 0 20px;
            color: inherit;
            font: 300 52px/1.04 var(--sans);
            letter-spacing: 0;
        }

        p {
            max-width: 380px;
            margin: 0;
            color: inherit;
            font: 400 18px/1.55 var(--serif);
        }
    }

    &__eyebrow {
        font: 500 11px/1.2 var(--sans-ext);
        letter-spacing: .11em;
        text-transform: uppercase;
    }

    &__articles {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 24px;
    }
}

#main-content .inspired-card {
    display: flex;
    min-width: 0;
    flex-direction: column;

    &__image {
        display: block;
        aspect-ratio: 4 / 5;
        overflow: hidden;
        background: #242424;

        img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            transition: transform .5s var(--ease);
        }

        &:hover img { transform: scale(1.025); }
    }

    &__meta {
        margin: 15px 0 7px;
        color: #686868;
        font: 500 11px/1.2 var(--sans-ext);
        letter-spacing: .1em;
        text-transform: uppercase;
    }

    h3 {
        min-height: 46px;
        margin: 0;
        color: inherit;
        font: 500 20px/1.15 var(--sans);
        letter-spacing: 0;
    }

    &__summary {
        margin: 20px 0 18px;
        color: #333;
        font: italic 400 14px/1.55 var(--serif);
    }

    &__actions {
        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 8px;
        margin-top: auto;
    }

    &__button {
        display: inline-flex;
        min-height: 46px;
        align-items: center;
        justify-content: center;
        border: 1px solid #111;
        background: #fff;
        color: #111;
        font: 500 11px/1.2 var(--sans-ext);
        letter-spacing: .09em;
        text-transform: uppercase;
        transition: background-color .2s ease, color .2s ease;

        &:hover {
            background: #111;
            color: #fff;
        }

        &--download {
            gap: 9px;
            background: #111;
            color: #fff !important;

            &::before {
                content: '';
                width: 9px;
                height: 11px;
                background: linear-gradient(#fff, #fff) 4px 0 / 1px 7px no-repeat,
                    linear-gradient(45deg, transparent 46%, #fff 48% 55%, transparent 57%) 1px 3px / 4px 5px no-repeat,
                    linear-gradient(-45deg, transparent 46%, #fff 48% 55%, transparent 57%) 4px 3px / 4px 5px no-repeat,
                    linear-gradient(#fff, #fff) center bottom / 9px 1px no-repeat;
            }

            &:hover {
                background: #333;
            }
        }
    }
}

@media (max-width: 1250px) {
    #main-content .stay-inspired {
        min-height: 0;
        padding-block: 72px;

        &__inner {
            grid-template-columns: 1fr;
            gap: 48px;
            max-width: 1232px;
        }

        &__intro {
            padding-top: 0;

            p { max-width: 570px; }
        }
    }
}

@media (max-width: 760px) {
    #main-content .stay-inspired {
        padding-block: 56px 64px;

        &__inner {
            gap: 40px;
        }

        &__intro {
            h2 {
                margin-block: 18px 16px;
                font-size: 40px;
            }

            p {
                font-size: 16px;
                line-height: 1.6;
            }
        }

        &__articles {
            grid-template-columns: 1fr;
            gap: 48px;
        }
    }

    #main-content .inspired-card h3 {
        min-height: 0;
    }

}

// The home content lives in the full-width hero block of Cornerstone.
#main-content { 
    > .container{
        padding: 0;
        max-width: 100%;
        width: 100%;
        margin: 0;
    }
}
#main-content:has(.twelve-home) { margin: 0; padding: 0; }
#main-content:has(.twelve-home) > .container:empty { display: none; }


// d19 supplied banner artwork. Keep Page Builder section styles unchanged.
.twelve-home {
    .hero-media .ph { display: block; position: absolute; inset: 0; height: 100%; overflow: hidden; isolation: isolate; background-size: cover; background-position: center; }
    .hero-media .ph::before { content: ''; position: absolute; inset: 0; z-index: 2; pointer-events: none; background: linear-gradient(180deg, rgba(0,0,0,.16), rgba(0,0,0,.08)); }
    .hero-media .ph::after { content: ''; position: absolute; inset: 0; pointer-events: none; background: radial-gradient(120% 90% at 50% 0%, rgba(255,255,255,.55), transparent 60%); }
    .bn-sustain { background-size: cover; background-position: center; isolation: isolate; background-position: center right !important; background-repeat: no-repeat !important; }
    @media (max-width: 760px) {
        .hero-media .ph::before { background: linear-gradient(180deg, rgba(0,0,0,.26) 0%, rgba(0,0,0,.12) 30%, rgba(0,0,0,.66) 64%, rgba(0,0,0,.82) 100%); }
    }
}

