@import "global-objects";

.alertBoxInfo{
    padding: 10px 50px 10px 16px;
    border-radius: 8px;
    border: 1px solid #707070;

    &.alertBoxInfo {
      padding: 10px 10px 10px 16px;
    }
    
    .alertBox-message, .alertBoxInfo-message{
        font-family: var(--sans-ext);
        font-size: 14px;
        font-weight: 400;
        line-height: 22px;
        text-align: left;
        color: #000000;
        margin: 0;
        span{
          width: 100%;
        }
    }
    
    .alertBox-column{
        vertical-align: text-top;
    }
    
    .icon {
        height: 18px;
        width: 20px;
        margin: -2px 0 0 0;
    }

    .alertBox-close{
        cursor: pointer;
        padding: 0;
        position: absolute;
        top: 0;
        width: 30px;
        height: 43px;
        right: 0;
        border-radius: 8px;
        svg{
            width: 22px;
            height: 22px;
            display: block;
            margin: 0 auto;
            fill: #838383 !important;
        }
        &:hover, &:focus {
            background-color:transparent !important;
            border-color: transparent;
        }
    }
    

  &.alertBoxInfo--info,
   &.alertBox--info{
       background: #E6F4FF;
       border-color:#91CAFF;
       svg{ fill: #000000; }
   }
   
   &.alertBoxInfo--success,
   &.alertBox--success{
       background: #F6FFED;
       border-color:#B7EB8F;
       svg{ fill: #52C41A; }
   }
   
   &.alertBoxInfo--warning,
   &.alertBox--warning{
       background:#FFFBE6;
       border-color: #FFE58F;
       svg{ fill:#FAAD14; }
   }
   
   &.alertBoxInfo--error,
   &.alertBox--error {
       background:#FFF1F0;
       border-color: #FFA39E;
       svg{ fill:#FF4D4F; }
   }
   
}

.bc-authentication-model {
