    width: 100%;
    height: 100%;
    position: fixed;
    padding: 15px;
    left: 0;
    top: 0;
    z-index: 9999999999;
    background: rgba($color: #000000, $alpha: 0.5);
    align-items: center;
    justify-content: center;
    backdrop-filter: blur(7px);

    .alertBox{
        display: none;
        margin-top: 0 !important;
        .icon{
