.step-counters{
    width: 100%;
    display: flex;
    flex: 1;
    margin-bottom:20px;
    border-bottom: 1px solid rgba($color: #000000, $alpha: 0.06);
    padding-bottom: 15px;
    @include emd-phone{
        flex-wrap: wrap;
        gap: 15px;
    }

    .step-counter{
        width: 100%;
        display: flex;
        align-items: center;
        gap: 10px;
        position: relative;
        z-index: 0;

        @include emd-phone{
            width: calc(50% - 10px);
        }

        .step-number{
            display: inline-flex;
            border-radius: 50%;
            width: 24px;
            height: 24px;
            background: #cccccc;
            font-family: var(--sans-ext);
            font-weight: 400;
            font-style: Regular;
            font-size: 14px;
            line-height: 22px;
            align-items: center;
            justify-content: center;
            position: relative;
            z-index: 1;
        }

        .step-title{
            width: calc(100% - 30px);
            font-family: var(--sans-ext);
            font-weight: 400;
            font-size: 14px;
            line-height: 22px;
            display: inline-flex;
            background: #fff;
            padding-right: 10px;
            background: #fff;
            position: relative;
            z-index: 1;
        }

        &::after{
            top: 50%;
            right: 10px;
            position: absolute;
            content: '';
            width:50%;
            height: 1px;
            background: #cccccc;
            z-index: 0;
        }

        &:last-child {
            width: auto;
            @include emd-phone{ 
                width: calc(50% - 10px);
            }
            .step-title{
                &::after{
                    display: none;
                }
                @include emd-phone{ 
                    &::after{
                        display: block !important;
                    }
                }
            }
        }

        &.is-active{
            .step-number{
                background: #000000;
                color: #fff;
            }
        }
        
        &.is-done{
            .step-number{
                background: #000000;
                color: transparent;
                &::after{
                    top: 0;
                    right: 0px;
                    position: absolute;
                    content: '';
                    width:100%;
                    height: 100%;
                    z-index: 0;
                    background-image: url("data:image/svg+xml,%3Csvg width='12' height='10' viewBox='0 0 12 10' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M11.4685 0.597656H10.5128C10.3788 0.597656 10.2517 0.65918 10.1697 0.764453L4.53274 7.90527L1.82981 4.48047C1.78892 4.42855 1.7368 4.38658 1.67737 4.35769C1.61794 4.3288 1.55273 4.31375 1.48665 4.31367H0.530983C0.439381 4.31367 0.388795 4.41895 0.44485 4.49004L4.18958 9.23418C4.36458 9.45566 4.7009 9.45566 4.87727 9.23418L11.5546 0.772656C11.6107 0.70293 11.5601 0.597656 11.4685 0.597656Z' fill='white'/%3E%3C/svg%3E%0A");
                    background-repeat: no-repeat;
                    background-position: center;
                }
            }
        }

    }
}



